package com.MITProjectService.bot.dao.jpaRepos;import com.MITProjectService.bot.domain.UserPaymentAccount;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.JpaSpecificationExecutor;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import java.util.Optional;@Repositorypublic interface UserPaymentAccountRepository extends JpaRepository<UserPaymentAccount, Long> , JpaSpecificationExecutor<UserPaymentAccount> {    @Query("SELECT u FROM UserPaymentAccount u WHERE u.serviceProvider.id = :userId")    Optional<UserPaymentAccount> findPaymentAccountByUserId(Long userId);}